plugins { alias(libs.plugins.android.library) }

// Optional shared build root used by the Floe local qualification flow. When
// it is absent (fresh public checkout) AGP keeps its normal module default.
val floeBuildRoot = providers.environmentVariable("FLOE_ANDROID_BUILD_ROOT").orNull

// Source-pinned embedded ADB pairing/transport primitives and the native
// starter used by Floe Full. This module NEVER ships a manager APK, a prebuilt
// executable or an opaque DEX/native blob: every binary is produced from the
// sources here and from the pinned upstream revision recorded in UPSTREAM.json.
//
// Main integration notes:
//  - add `include(":vendor:embedded-shizuku")` to settings.gradle.kts;
//  - add `api(project(":vendor:embedded-shizuku"))` to :feature:rootsystem;
//  - the Full App must package native libs with `useLegacyPackaging = true`
//    (or android:extractNativeLibs="true") so `libfloe_starter.so` is
//    executable from nativeLibraryDir, exactly like upstream Shizuku;
//  - do not include this module from the Play variant.
android {
    namespace = "moe.shizuku.embedded"
    compileSdk = 37
    ndkVersion = "30.0.16248370"
    defaultConfig {
        minSdk = 28
        ndk { abiFilters += "arm64-v8a" }
        externalNativeBuild {
            cmake {
                arguments += listOf("-DANDROID_STL=none")
                cppFlags += listOf("-std=c++17", "-fno-exceptions", "-fno-rtti")
            }
        }
    }
    buildFeatures { prefab = true }
    externalNativeBuild {
        cmake {
            path = file("src/main/cpp/CMakeLists.txt")
            version = "3.22.1"
            // Pin staging beside the redirected module build dir so a shared
            // Floe build root cannot scatter CMake output under the App build.
            floeBuildRoot?.let { root ->
                buildStagingDirectory = File(root, "vendor/embedded-shizuku/.cxx")
            }
        }
    }
    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }
}

dependencies {
    // Pinned native dependencies used by the upstream Shizuku JNI build
    // (Apache-2.0 Shizuku, BoringSSL and libc++ builds). Prefab packages are
    // consumed only by the CMake targets; no Java API is exposed.
    implementation("io.github.vvb2060.ndk:boringssl:20250114")
    implementation("org.lsposed.libcxx:libcxx:27.0.12077973")
    testImplementation(libs.junit)
    // gradle.lockfile is regenerated by Main's serialized --write-locks stage.
}
